/**
 * This contains the results of checking the complexity of a given
 * password - that is, how good of a password, how secure, is it?
 * See {@link com.coveros.training.authentication.RegistrationUtils#isPasswordGood}
 * for the calculation that generates this.
 */
public final class PasswordResult {
    public final com.coveros.training.authentication.domainobjects.PasswordResultEnums status;

    private final java.lang.Double entropy;

    public final java.lang.String timeToCrackOffline;

    private final java.lang.String timeToCrackOnline;

    private final java.lang.String message;

    private static final java.lang.String BASIC_PASSWORD_CHECKS_FAILED = "BASIC_PASSWORD_CHECKS_FAILED";

    public PasswordResult(com.coveros.training.authentication.domainobjects.PasswordResultEnums status, java.lang.Double entropy, java.lang.String timeToCrackOffline, java.lang.String timeToCrackOnline, java.lang.String message) {
        this.status = status;
        this.entropy = entropy;
        this.timeToCrackOffline = timeToCrackOffline;
        this.timeToCrackOnline = timeToCrackOnline;
        this.message = message;
    }

    /**
     * Return this if any of our very basic attempt to validate
     * the password field fail.  Like passing an empty string, for example.
     */
    public static com.coveros.training.authentication.domainobjects.PasswordResult createDefault(com.coveros.training.authentication.domainobjects.PasswordResultEnums resultStatus) {
        return new com.coveros.training.authentication.domainobjects.PasswordResult(resultStatus, 0.0, "", "", com.coveros.training.authentication.domainobjects.PasswordResult.BASIC_PASSWORD_CHECKS_FAILED);
    }

    @java.lang.Override
    public final boolean equals(@org.checkerframework.checker.nullness.qual.Nullable
    java.lang.Object obj) {
        if (obj == null) {
            return false;
        }
        if (obj == this) {
            return true;
        }
        if (obj.getClass() != getClass()) {
            return false;
        }
        com.coveros.training.authentication.domainobjects.PasswordResult rhs = ((com.coveros.training.authentication.domainobjects.PasswordResult) (obj));
        return new org.apache.commons.lang3.builder.EqualsBuilder().append(status, rhs.status).append(entropy, rhs.entropy).append(timeToCrackOffline, rhs.timeToCrackOffline).append(timeToCrackOnline, rhs.timeToCrackOnline).append(message, rhs.message).isEquals();
    }

    @java.lang.Override
    public final int hashCode() {
        // you pick a hard-coded, randomly chosen, non-zero, odd number
        // ideally different for each class
        return new org.apache.commons.lang3.builder.HashCodeBuilder(15, 33).append(status).append(entropy).append(timeToCrackOffline).append(timeToCrackOnline).append(message).toHashCode();
    }

    public final java.lang.String toString() {
        return org.apache.commons.lang3.builder.ToStringBuilder.reflectionToString(this);
    }

    public final java.lang.String toPrettyString() {
        return (((java.lang.String.format("status: %s%n", status) + java.lang.String.format("entropy: %s%n", entropy)) + java.lang.String.format("time to crack offline: %s%n", timeToCrackOffline)) + java.lang.String.format("time to crack online: %s%n", timeToCrackOnline)) + java.lang.String.format("Nbvcxz response: %s%n", message);
    }

    /**
     * Return this to represent an empty result.  Used primarily
     * when we are initializing a variable and don't want to use null.
     */
    public static com.coveros.training.authentication.domainobjects.PasswordResult createEmpty() {
        return new com.coveros.training.authentication.domainobjects.PasswordResult(com.coveros.training.authentication.domainobjects.PasswordResultEnums.NULL, 0.0, "", "", "");
    }

    public boolean isEmpty() {
        return this.equals(com.coveros.training.authentication.domainobjects.PasswordResult.createEmpty());
    }
}

/**
 * All the values currently possible for our
 * assessment of a potential password
 */
public enum PasswordResultEnums {

    TOO_SHORT,
    /**
     * ironic, I know, but if it's too long we're open to DOS attacks.
     * It takes too long to process extremely long passwords.
     */
    TOO_LONG,
    EMPTY_PASSWORD,
    /**
     * as measured by a tool.  See implementation where this is used.
     */
    INSUFFICIENT_ENTROPY,
    SUCCESS,
    /**
     * This is only used for empty password results.  See {@link PasswordResult#createEmpty()}
     */
    NULL;}

public class PasswordResultTests {
    @org.junit.Test
    public void testShouldHaveEqualsAndHashcodeImplementedCorrectly() {
        nl.jqno.equalsverifier.EqualsVerifier.forClass(com.coveros.training.authentication.domainobjects.PasswordResult.class).verify();
