        org.junit.Assert.assertTrue("was " + passwordResult, (((result.contains("status=SUCCESS") && result.contains("entropy=0.0")) && result.contains("timeToCrackOffline=")) && result.contains("timeToCrackOnline=")) && result.contains("message=BASIC_PASSWORD_CHECKS_FAILED"));
    }

    private static com.coveros.training.authentication.domainobjects.PasswordResult createTestPasswordResult() {
        return com.coveros.training.authentication.domainobjects.PasswordResult.createDefault(com.coveros.training.authentication.domainobjects.PasswordResultEnums.SUCCESS);
    }

    @org.junit.Test
    public void testCanCreateEmpty() {
        final com.coveros.training.authentication.domainobjects.PasswordResult passwordResult = com.coveros.training.authentication.domainobjects.PasswordResult.createEmpty();
        org.junit.Assert.assertTrue(passwordResult.isEmpty());
    }
