/**
 * Provides an API endpoint for login.
 * <p>
 * A user (librarian) enters their username and password to authenticate.
 * </p>
 */
@javax.servlet.annotation.WebServlet(name = "LoginServlet", urlPatterns = { "/login" }, loadOnStartup = 1)
public class LoginServlet extends javax.servlet.http.HttpServlet {
    private static final long serialVersionUID = 7302828964216520580L;

    private static final org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(com.coveros.training.authentication.LoginServlet.class);

    static com.coveros.training.authentication.LoginUtils loginUtils = new com.coveros.training.authentication.LoginUtils();

    @java.lang.Override
    protected void doPost(javax.servlet.http.HttpServletRequest request, javax.servlet.http.HttpServletResponse response) {
        java.lang.String username = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter("username"));
        request.setAttribute("username", username);
        java.lang.String password = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter("password"));
        request.setAttribute("password", password);
        java.lang.String responseText;
        if (username.isEmpty()) {
            responseText = "no username provided";
        } else if (password.isEmpty()) {
            responseText = "no password provided";
        } else {
            com.coveros.training.authentication.LoginServlet.logger.info("received request to authenticate a user, {}", username);
            final boolean userRegistered = com.coveros.training.authentication.LoginServlet.loginUtils.isUserRegistered(username, password);
            responseText = (userRegistered) ? "access granted" : "access denied";
        }
        request.setAttribute("result", responseText);
        request.setAttribute("return_page", "library.html");
        com.coveros.training.helpers.ServletUtils.forwardToResult(request, response, com.coveros.training.authentication.LoginServlet.logger);
    }
}

