/**
 * These tests cover the testing of the endpoint itself, not so much
 * anything it calls.  That's why we mock out everything outside
 * this class.  It makes our tests run very quickly, and enables us to
 * focus with laser-like precision on the functionality this class
 * provides.  Other tests will provide integration testing - but not
 * this one.
 */
public class LoginServletTests {
    public static final java.lang.String DEFAULT_USERNAME = "alice";

    public static final java.lang.String DEFAULT_PASSWORD = "abc123";

    private javax.servlet.http.HttpServletRequest request = org.mockito.Mockito.mock(javax.servlet.http.HttpServletRequest.class);

    private javax.servlet.http.HttpServletResponse response = org.mockito.Mockito.mock(javax.servlet.http.HttpServletResponse.class);

    private javax.servlet.RequestDispatcher requestDispatcher = org.mockito.Mockito.mock(javax.servlet.RequestDispatcher.class);

    private com.coveros.training.authentication.LoginServlet loginServlet = spy(new com.coveros.training.authentication.LoginServlet());

    /**
     * We'll be mocking requests and responses and so on throughout these
     * tests, so just initialize them here for later use.  Notice
     * that we use spy for the LoginServlet.  This specifically allows us to mock
     * out its loginUtils class, but otherwise, all LoginServlet calls
     * are to the real code.  Why mock LoginUtils? So that we can prevent
     * real calls into that class - it's assumed we have already tested
     * that class on its own, we just want to test code specific to this class.
     *
     * LoginServlet uses a static method, {@link ServletUtils#forwardToResult}
     * that has a call to {@link HttpServletRequest#getRequestDispatcher} that
     * we need to mock out.
     */
    @org.junit.Before
    public void before() {
        request = mock(javax.servlet.http.HttpServletRequest.class);
        response = mock(javax.servlet.http.HttpServletResponse.class);
        requestDispatcher = mock(javax.servlet.RequestDispatcher.class);
        loginServlet = spy(new com.coveros.training.authentication.LoginServlet());
        com.coveros.training.authentication.LoginServlet.loginUtils = org.mockito.Mockito.mock(com.coveros.training.authentication.LoginUtils.class);
        // this is always called in a static method, it's boilerplate for these tests.
        when(request.getRequestDispatcher(com.coveros.training.helpers.ServletUtils.RESULT_JSP)).thenReturn(requestDispatcher);
    }

    /**
     * The basic happy path - a username and password are entered
     */
    @org.junit.Test
    public void testHappyPathPost() {
        // not the greatest password in the world, but we're not testing that
        // at this level - rather, just that the endpoint got a password at all
        setMock_UsernameAndPassword(com.coveros.training.authentication.LoginServletTests.DEFAULT_USERNAME, com.coveros.training.authentication.LoginServletTests.DEFAULT_PASSWORD);
        setMock_LoginUtilsUserRegistered(com.coveros.training.authentication.LoginServletTests.DEFAULT_USERNAME, com.coveros.training.authentication.LoginServletTests.DEFAULT_PASSWORD, true);
        loginServlet.doPost(request, response);
        verifyExpectedResult("access granted");
    }

    /**
     * If a particular username and password are not registered, login will fail.  access denied.
     */
    @org.junit.Test
    public void testShouldGetAccessDeniedIfUserNotRegistered() {
        setMock_UsernameAndPassword(com.coveros.training.authentication.LoginServletTests.DEFAULT_USERNAME, com.coveros.training.authentication.LoginServletTests.DEFAULT_PASSWORD);
        setMock_LoginUtilsUserRegistered(com.coveros.training.authentication.LoginServletTests.DEFAULT_USERNAME, com.coveros.training.authentication.LoginServletTests.DEFAULT_PASSWORD, false);
        loginServlet.doPost(request, response);
        verifyExpectedResult("access denied");
    }

    /**
     * If they pass in an empty string for username, it should return a message
     * indicating that.
     */
    @org.junit.Test
    public void testEmptyString_Username() {
        // Empty string for the username.
        setMock_UsernameAndPassword("", com.coveros.training.authentication.LoginServletTests.DEFAULT_PASSWORD);
        loginServlet.doPost(request, response);
        verifyExpectedResult("no username provided");
    }

    /**
     * If they pass in an empty string for password, it should return a message
     * indicating that.
     */
    @org.junit.Test
    public void testEmptyString_Password() {
        // Empty string for the password.
        setMock_UsernameAndPassword(com.coveros.training.authentication.LoginServletTests.DEFAULT_USERNAME, "");
        loginServlet.doPost(request, response);
        verifyExpectedResult("no password provided");
    }

    /**
     * Mock out the username and password values on the request, the
     * user's input to this endpoint
     */
    private void setMock_UsernameAndPassword(java.lang.String username, java.lang.String password) {
        when(request.getParameter("username")).thenReturn(username);
        when(request.getParameter("password")).thenReturn(password);
    }

    /**
     * Mock out the call and response for LoginUtils, so we can
     * better control how our endpoint will behave in different situations
     *
     * @param username
     * 		check this if already registered
     * @param password
     * 		check this if already registered
     * @param expectedReturn
     * 		what we want the call to return for the purposes of our test
     */
    private void setMock_LoginUtilsUserRegistered(java.lang.String username, java.lang.String password, boolean expectedReturn) {
        when(com.coveros.training.authentication.LoginServlet.loginUtils.isUserRegistered(username, password)).thenReturn(expectedReturn);
    }

    /**
     * A wrapper around the mock just to better document intention
     *
     * @param expectedResult
     * 		what we expect as the bottom-line result,
     * 		which will end up sent to the user as a message
     */
    private void verifyExpectedResult(java.lang.String expectedResult) {
        org.mockito.Mockito.verify(request).setAttribute("result", expectedResult);
    }
}

public class LoginStepDefs {
    private boolean isRegisteredUser;

    private com.coveros.training.authentication.RegistrationUtils registrationUtils = com.coveros.training.authentication.RegistrationUtils.createEmpty();

    private com.coveros.training.authentication.LoginUtils loginUtils = com.coveros.training.authentication.LoginUtils.createEmpty();

    private final com.coveros.training.persistence.IPersistenceLayer pl = new com.coveros.training.persistence.PersistenceLayer();

    /**
     * create objects for registration and login, and clear the database.
     */
    private void initializeDatabaseAccess() {
        pl.cleanAndMigrateDatabase();
        registrationUtils = new com.coveros.training.authentication.RegistrationUtils();
        loginUtils = new com.coveros.training.authentication.LoginUtils();
    }

    @io.cucumber.java.en.Given("^\"([^\"]*)\" is registered in the system with the password \"([^\"]*)\"$")
    public void isRegisteredInSystemWithPassword(java.lang.String username, java.lang.String password) {
        initializeDatabaseAccess();
        registrationUtils.processRegistration(username, password);
    }

    @io.cucumber.java.en.Then("^The system decides that they are authenticated.$")
    public void theSystemDecidesThatTheyAreAuthenticated() {
        org.junit.Assert.assertTrue(isRegisteredUser);
    }

    @io.cucumber.java.en.Then("^The system decides that they are not authenticated, because .*$")
    public void theSystemDecidesThatTheyAreNotAuthenticated() {
        org.junit.Assert.assertFalse(isRegisteredUser);
    }

    @io.cucumber.java.en.When("^when a user authenticates with \"([^\"]*)\" and \"([^\"]*)\"$")
    public void whenAUserAuthenticatesWithAnd(java.lang.String username, java.lang.String password) {
        isRegisteredUser = loginUtils.isUserRegistered(username, password);
    }
}

/**
 * Provides business-layer for determining if entered credentials qualify for authentication
 */
public class LoginUtils {
    private static final org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(com.coveros.training.authentication.LoginUtils.class);

    private final com.coveros.training.persistence.IPersistenceLayer persistenceLayer;

    public LoginUtils(com.coveros.training.persistence.IPersistenceLayer persistenceLayer) {
        this.persistenceLayer = persistenceLayer;
    }

    public LoginUtils() {
        this(new com.coveros.training.persistence.PersistenceLayer());
    }

    /**
     * Determine if input is correct credentials for a registered user.
     *
     * @return true if the credentials are valid, false otherwise
     */
    public boolean isUserRegistered(java.lang.String username, java.lang.String password) {
        com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(username, password);
        com.coveros.training.authentication.LoginUtils.logger.info("checking if credentials for {} are valid for login", username);
        boolean isValid = persistenceLayer.areCredentialsValid(username, password).orElse(false);
        if (isValid) {
            com.coveros.training.authentication.LoginUtils.logger.info("credentials for {} are valid - granting access", username);
        } else {
            com.coveros.training.authentication.LoginUtils.logger.info("credentials for {} were invalid - denying access", username);
        }
        return isValid;
    }

    public static com.coveros.training.authentication.LoginUtils createEmpty() {
        return new com.coveros.training.authentication.LoginUtils(com.coveros.training.persistence.PersistenceLayer.createEmpty());
    }

    public boolean isEmpty() {
        return persistenceLayer.isEmpty();
    }
}

public class LoginUtilsTests {
    private com.coveros.training.persistence.IPersistenceLayer mockPersistenceLayer = org.mockito.Mockito.mock(com.coveros.training.persistence.IPersistenceLayer.class);

    private com.coveros.training.authentication.LoginUtils loginUtils = org.mockito.Mockito.spy(new com.coveros.training.authentication.LoginUtils(mockPersistenceLayer));

    @org.junit.Before
    public void init() {
        mockPersistenceLayer = org.mockito.Mockito.mock(com.coveros.training.persistence.IPersistenceLayer.class);
        loginUtils = org.mockito.Mockito.spy(new com.coveros.training.authentication.LoginUtils(mockPersistenceLayer));
    }

    @org.junit.Test
    public void testCanCreateEmpty() {
        final com.coveros.training.authentication.LoginUtils loginUtils = com.coveros.training.authentication.LoginUtils.createEmpty();
        org.junit.Assert.assertTrue(loginUtils.isEmpty());
    }

    @org.junit.Test
    public void testCanSeeIfUserRegistered() {
        loginUtils.isUserRegistered("alice", "abc123");
        org.mockito.Mockito.verify(mockPersistenceLayer, times(1)).areCredentialsValid("alice", "abc123");
    }
}

