    private final com.coveros.training.authentication.RegistrationUtils registrationUtils = new com.coveros.training.authentication.RegistrationUtils(persistenceLayer);

    /**
     * a really short password can be found by brute force extremely quickly,
     * making this highly insecure
     */
    @org.junit.Test
    public void testShouldFailOnShortPassword() {
        final com.coveros.training.authentication.domainobjects.PasswordResult result = com.coveros.training.authentication.RegistrationUtils.isPasswordGood("abc");
        org.junit.Assert.assertEquals(com.coveros.training.authentication.domainobjects.PasswordResultEnums.TOO_SHORT, result.status);
    }

    @org.junit.Test
    public void testShouldFailOnEmptyPassword_EmptyString() {
        final com.coveros.training.authentication.domainobjects.PasswordResult result = com.coveros.training.authentication.RegistrationUtils.isPasswordGood("");
        org.junit.Assert.assertEquals(com.coveros.training.authentication.domainobjects.PasswordResultEnums.EMPTY_PASSWORD, result.status);
    }

    /**
     * A lightweight performance test for a slow call
     */
    @org.junit.Ignore
    @org.junit.Test
    public void testShouldPerformWell() {
        long start = java.lang.System.currentTimeMillis();
        final java.util.List<java.lang.String> goodPasswords = java.util.Arrays.asList("XaZE}SkOC/@k#blv}U+wOlDfj=a]q", "-MzlAim%Zuh.=B|8N|Vd~`l5?*Cs,ZH\\\'l/76t-9]W\\D$Il#vynO+~y_@", "lm=U(#C;@Bl*jvEy_*U1QlR@3sje");
        for (java.lang.String password : goodPasswords) {
            com.coveros.training.authentication.RegistrationUtils.isPasswordGood(password);
        }
        long finish = java.lang.System.currentTimeMillis();
        long timeElapsed = finish - start;
        org.junit.Assert.assertTrue(("All these calls should have finished in a short time.  " + "Time elapsed was ") + timeElapsed, timeElapsed < 1500);
    }

    /**
     * If we provide a good password, then by golly we should get that
     * as a result from our {@link RegistrationUtils#isPasswordGood} method.
     */
    @org.junit.Test
    public void testShouldHaveSufficientEntropyInPassword() {
        final com.coveros.training.authentication.domainobjects.PasswordResult result = com.coveros.training.authentication.RegistrationUtils.isPasswordGood(com.coveros.training.authentication.RegistrationUtilsTests.GOOD_PASSWORD);
        org.junit.Assert.assertEquals(com.coveros.training.authentication.domainobjects.PasswordResultEnums.SUCCESS, result.status);
    }

    /**
     * Not really a lot to test here...
     */
    @org.junit.Test
    public void testShouldDetermineIfUserInDatabase() {
        // mock that a user is found when we search for them
        Mockito.when(persistenceLayer.searchForUserByName(com.coveros.training.authentication.RegistrationUtilsTests.ALICE)).thenReturn(java.util.Optional.of(new com.coveros.training.authentication.domainobjects.User(com.coveros.training.authentication.RegistrationUtilsTests.ALICE, 1)));
        final boolean result = registrationUtils.isUserInDatabase(com.coveros.training.authentication.RegistrationUtilsTests.ALICE);
        org.junit.Assert.assertTrue(result);
    }

    /**
     * Testing registration without hitting the actual database.
     * The password has to be sufficient to meet the entropy stipulations.
     * We need to mock the calls that will have been sent to the database.
     */
    @org.junit.Test
    public void testShouldProcessRegistration_HappyPath() {
        // this needs to not find a user
        Mockito.when(persistenceLayer.searchForUserByName(com.coveros.training.authentication.RegistrationUtilsTests.ALICE)).thenReturn(java.util.Optional.empty());
        com.coveros.training.authentication.domainobjects.RegistrationResult expectedResult = new com.coveros.training.authentication.domainobjects.RegistrationResult(true, com.coveros.training.authentication.domainobjects.RegistrationStatusEnums.SUCCESSFULLY_REGISTERED);
        final com.coveros.training.authentication.domainobjects.RegistrationResult registrationResult = registrationUtils.processRegistration(com.coveros.training.authentication.RegistrationUtilsTests.ALICE, com.coveros.training.authentication.RegistrationUtilsTests.GOOD_PASSWORD);
        org.junit.Assert.assertEquals(expectedResult, registrationResult);
    }

    @org.junit.Rule
    public org.junit.rules.ExpectedException thrown = org.junit.rules.ExpectedException.none();

    /**
     * If we pass in an empty username, we should get a response that
     * registration failed.
     */
    @org.junit.Test
    public void testShouldProcessRegistration_EmptyUsername() {
        thrown.expect(java.lang.IllegalArgumentException.class);
        thrown.expectMessage("string must not be null or empty at this point");
        registrationUtils.processRegistration("", com.coveros.training.authentication.RegistrationUtilsTests.GOOD_PASSWORD);
    }

    /**
     * Registration should fail if the password isn't good enough.
     */
    @org.junit.Test
    public void testShouldProcessRegistration_BadPassword() {
        // this needs to not find a user
        Mockito.when(persistenceLayer.searchForUserByName(com.coveros.training.authentication.RegistrationUtilsTests.ALICE)).thenReturn(java.util.Optional.empty());
        final com.coveros.training.authentication.domainobjects.PasswordResult result = com.coveros.training.authentication.RegistrationUtils.isPasswordGood(com.coveros.training.authentication.RegistrationUtilsTests.BAD_PASSWORD);
        com.coveros.training.authentication.domainobjects.RegistrationResult expectedResult = new com.coveros.training.authentication.domainobjects.RegistrationResult(false, com.coveros.training.authentication.domainobjects.RegistrationStatusEnums.BAD_PASSWORD, result.toPrettyString());
        final com.coveros.training.authentication.domainobjects.RegistrationResult registrationResult = registrationUtils.processRegistration(com.coveros.training.authentication.RegistrationUtilsTests.ALICE, com.coveros.training.authentication.RegistrationUtilsTests.BAD_PASSWORD);
        org.junit.Assert.assertEquals(expectedResult, registrationResult);
    }

    /**
     * Registration should fail if we're trying to register an already-existing user.
     */
    @org.junit.Test
    public void testShouldProcessRegistration_ExistingUser() {
        // this needs to find an existing user - so they are already registered
        Mockito.when(persistenceLayer.searchForUserByName(com.coveros.training.authentication.RegistrationUtilsTests.ALICE)).thenReturn(java.util.Optional.of(new com.coveros.training.authentication.domainobjects.User(com.coveros.training.authentication.RegistrationUtilsTests.ALICE, 1)));
        com.coveros.training.authentication.domainobjects.RegistrationResult expectedResult = new com.coveros.training.authentication.domainobjects.RegistrationResult(false, com.coveros.training.authentication.domainobjects.RegistrationStatusEnums.ALREADY_REGISTERED);
        final com.coveros.training.authentication.domainobjects.RegistrationResult registrationResult = registrationUtils.processRegistration(com.coveros.training.authentication.RegistrationUtilsTests.ALICE, com.coveros.training.authentication.RegistrationUtilsTests.GOOD_PASSWORD);
        org.junit.Assert.assertEquals(expectedResult, registrationResult);
    }

    @org.junit.Test
    public void testEmptyObject() {
        final com.coveros.training.authentication.RegistrationUtils registrationUtils = com.coveros.training.authentication.RegistrationUtils.createEmpty();
        org.junit.Assert.assertTrue(registrationUtils.isEmpty());
    }
