public class AutoInsuranceScriptClient {
    public static final java.lang.String QUIT = "quit";

    static org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(com.coveros.training.autoinsurance.AutoInsuranceScriptClient.class);

    public java.lang.String send(java.lang.String command) {
        java.lang.String hostName = "localhost";
        java.lang.String result = "";
        int portNumber = 8000;
        try (java.net.Socket echoSocket = new java.net.Socket(hostName, portNumber)) {
            java.io.PrintWriter out = new java.io.PrintWriter(echoSocket.getOutputStream(), true);
            java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(echoSocket.getInputStream()));
            com.coveros.training.autoinsurance.AutoInsuranceScriptClient.logger.info("running command: {}", command);
            if (command.equals(com.coveros.training.autoinsurance.AutoInsuranceScriptClient.QUIT)) {
                result = processCommand(out, in, command);
            }
            result = processCommand(out, in, command);
        } catch (java.net.UnknownHostException e) {
            com.coveros.training.autoinsurance.AutoInsuranceScriptClient.logger.error("Don't know about host {}", hostName);
        } catch (java.io.IOException e) {
            com.coveros.training.autoinsurance.AutoInsuranceScriptClient.logger.error("Couldn't get I/O for the connection to {}", hostName);
        }
        return result;
    }

    private java.lang.String processCommand(java.io.PrintWriter out, java.io.BufferedReader in, java.lang.String command) throws java.io.IOException {
        com.coveros.training.autoinsurance.AutoInsuranceScriptClient.logger.info("sending: {}", command);
        out.println(command);
        final java.lang.String response = in.readLine();
        com.coveros.training.autoinsurance.AutoInsuranceScriptClient.logger.info("response: {}", response);
        return response;
    }
}

