public class AutoInsuranceScriptServer implements java.lang.Runnable , java.beans.Transient {
    static org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(com.coveros.training.autoinsurance.AutoInsuranceScriptServer.class);

    private boolean shouldRepeat = true;

    private com.coveros.training.autoinsurance.AutoInsuranceUI autoInsuranceUI;

    /**
     * Construct this with access to the UI we can control
     *
     * @param autoInsuranceUI
     * 		the UI we are controlling
     */
    public AutoInsuranceScriptServer(com.coveros.training.autoinsurance.AutoInsuranceUI autoInsuranceUI) {
        this.autoInsuranceUI = autoInsuranceUI;
    }

    public void serverStart() {
        int portNumber = 8000;
        while (shouldRepeat) {
            try (java.net.ServerSocket serverSocket = new java.net.ServerSocket(portNumber);java.net.Socket clientSocket = serverSocket.accept()) {
                java.io.PrintWriter out = new java.io.PrintWriter(clientSocket.getOutputStream(), true);
                java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(clientSocket.getInputStream()));
                java.lang.String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    java.lang.String result = "OK";
                    final java.lang.String[] inputTokens = java.util.Arrays.stream(inputLine.split(" ")).map(java.lang.String::toLowerCase).toArray(java.lang.String[]::new);
                    try {
                        handleQuit(inputTokens);
                        handleSetCases(inputTokens);
                        result = handleGetCases(result, inputTokens);
                        handleClickActions(inputTokens);
                    } catch (java.lang.Exception ex) {
                        com.coveros.training.autoinsurance.AutoInsuranceScriptServer.logger.error(ex.getMessage());
                        result = "FAILURE";
                    }
                    out.println(result);
                } 
            } catch (java.io.IOException e) {
                com.coveros.training.autoinsurance.AutoInsuranceScriptServer.logger.error(("Exception caught when trying to listen on port " + portNumber) + " or listening for a connection");
                com.coveros.training.autoinsurance.AutoInsuranceScriptServer.logger.error(e.getMessage());
            }
        } 
    }

    private void handleClickActions(java.lang.String[] inputTokens) {
        if (inputTokens[0].equals("click") && inputTokens[1].equals("calculate")) {
            autoInsuranceUI.claimsCalcButton.doClick();
        }
    }

    private java.lang.String handleGetCases(java.lang.String result, java.lang.String[] inputTokens) {
        if (inputTokens[0].equals("get")) {
            if (inputTokens[1].equals("label")) {
                result = autoInsuranceUI.label.getText();
            }
            if (inputTokens[1].equals("age")) {
                result = autoInsuranceUI.ageField.getText();
            }
            if (inputTokens[1].equals("claims")) {
                result = autoInsuranceUI.claimsDropDown.getSelectedItem().toString();
            }
        }
        return result;
    }

    private void handleSetCases(java.lang.String[] inputTokens) {
        if (inputTokens[0].equals("set")) {
            if (inputTokens[1].equals("label")) {
                autoInsuranceUI.setLabel(inputTokens[2]);
            }
            if (inputTokens[1].equals("age")) {
                autoInsuranceUI.setClaimsAge(inputTokens[2]);
            }
            if (inputTokens[1].equals("claims")) {
                final int i = java.lang.Integer.parseInt(inputTokens[2]);
                autoInsuranceUI.setPreviousClaims(i);
            }
        }
    }

    private void handleQuit(java.lang.String[] inputTokens) {
        if (inputTokens[0].equals("quit")) {
            shouldRepeat = false;
        }
    }

    @java.lang.Override
    public void run() {
        serverStart();
    }

    @java.lang.Override
    public boolean value() {
        return false;
    }

    @java.lang.Override
    public java.lang.Class<? extends java.lang.annotation.Annotation> annotationType() {
        return null;
    }
}

