public class AutoInsuranceUI extends javax.swing.JPanel {
    // server used for automating the UI
    com.coveros.training.autoinsurance.AutoInsuranceScriptServer autoInsuranceScriptServer;

    javax.swing.JLabel label;

    javax.swing.JComboBox<java.lang.String> claimsDropDown;

    javax.swing.JTextField ageField;

    javax.swing.JButton claimsCalcButton;

    javax.swing.JFrame frame;

    /**
     * Creates the GUI shown inside the frame's content pane.
     */
    public AutoInsuranceUI(javax.swing.JFrame frame) {
        super(new java.awt.BorderLayout());
        this.frame = frame;
        javax.swing.JPanel autoInsurancePanel = createAutoInsurancePanel();
        // Lay them out.
        javax.swing.border.Border padding = javax.swing.BorderFactory.createEmptyBorder(20, 20, 5, 20);
        autoInsurancePanel.setBorder(padding);
        add(autoInsurancePanel, java.awt.BorderLayout.CENTER);
        label = new javax.swing.JLabel("Click the \"Crunch\" button" + " to calculate your auto insurance results", javax.swing.SwingConstants.CENTER);
        add(label, java.awt.BorderLayout.PAGE_END);
        label.setBorder(javax.swing.BorderFactory.createEmptyBorder(10, 10, 10, 10));
        startSocketServer();
    }

    private javax.swing.JPanel createAutoInsurancePanel() {
        javax.swing.JPanel box = new javax.swing.JPanel();
        box.setLayout(new javax.swing.BoxLayout(box, javax.swing.BoxLayout.PAGE_AXIS));
        addLabel(box, "Previous claims:");
        claimsDropDown = addClaimsDropDown(box);
        addLabel(box, "Driver's age:");
        ageField = addClaimsAgeTextField(box);
        claimsCalcButton = addClaimsCalcButton(box);
        claimsCalcButton.addActionListener(e -> {
            final int intPreviousClaims = getIntPreviousClaims();
            final java.lang.String customerAge = ageField.getText();
            final int intCustomerAge = java.lang.Integer.parseInt(customerAge);
            final com.coveros.training.autoinsurance.AutoInsuranceAction result = com.coveros.training.autoinsurance.AutoInsuranceProcessor.process(intPreviousClaims, intCustomerAge);
            setLabel((((("Premium increase: $" + result.premiumIncreaseDollars) + " Warning Ltr: ") + result.warningLetterEnum) + " is canceled: ") + result.isPolicyCanceled);
        });
        return box;
    }

    /**
     * This method returns an integer representing the number of previous claims for a customer.
     */
    private int getIntPreviousClaims() {
        final java.lang.String numberPreviousClaims = ((java.lang.String) (claimsDropDown.getSelectedItem()));
        assert numberPreviousClaims != null;
        switch (numberPreviousClaims) {
            case "0" :
                return 0;
            case "1" :
                return 1;
            case "2-4" :
                return 2;
            case ">=5" :
                return 5;
            default :
                throw new com.coveros.training.autoinsurance.InvalidClaimsException("invalid value entered");
        }
    }

    private javax.swing.JTextField addClaimsAgeTextField(javax.swing.JPanel box) {
        javax.swing.JTextField textField = new javax.swing.JTextField();
        textField.setVisible(true);
        box.add(textField);
        return textField;
    }

    private javax.swing.JButton addClaimsCalcButton(javax.swing.JPanel box) {
        javax.swing.JButton crunch = new javax.swing.JButton("Crunch");
        crunch.setVisible(true);
        box.add(crunch);
        return crunch;
    }

    private void addLabel(javax.swing.JPanel box, java.lang.String msg) {
        javax.swing.JLabel lbl = new javax.swing.JLabel(msg);
        lbl.setVisible(true);
        box.add(lbl);
    }

    private javax.swing.JComboBox<java.lang.String> addClaimsDropDown(javax.swing.JPanel box) {
        java.lang.String[] previousClaims = new java.lang.String[]{ "0", "1", "2-4", ">=5" };
        final javax.swing.JComboBox<java.lang.String> cb = new javax.swing.JComboBox<>(previousClaims);
        cb.setVisible(true);
        box.add(cb);
        return cb;
    }

    /**
     * start a socket server that can run commands on this UI.
     * This is to enable automation scripts.
     */
    private void startSocketServer() {
        autoInsuranceScriptServer = new com.coveros.training.autoinsurance.AutoInsuranceScriptServer(this);
        java.lang.Thread newThread = new java.lang.Thread(autoInsuranceScriptServer);
        newThread.start();
    }

    /**
     * Sets the text at the bottom of the panel
     *
     * @param newText
     * 		whatever you want the new text to be
     */
    void setLabel(java.lang.String newText) {
        label.setText(newText);
    }

    /**
     * Selects one of the drop-down items for previous claims
     *
     * @param claims
     * 		number of previous claims
     */
    void setPreviousClaims(int claims) {
        if (claims <= 0) {
            claimsDropDown.setSelectedIndex(0);
        }
        if (claims == 1) {
            claimsDropDown.setSelectedIndex(1);
        }
        if ((claims >= 2) && (claims <= 4)) {
            claimsDropDown.setSelectedIndex(2);
        }
        if (claims >= 5) {
            claimsDropDown.setSelectedIndex(3);
        }
    }

    /**
     * Sets the age field per what you enter
     *
     * @param age
     * 		the text that goes into the age field.
     */
    void setClaimsAge(java.lang.String age) {
        ageField.setText(age);
    }

    /**
     * Create the GUI and show it.  For thread safety,
     * this method should be invoked from the
     * event-dispatching thread.
     */
    private static void createAndShowGUI() {
        // Create and set up the window.
        javax.swing.JFrame frame = new javax.swing.JFrame("AutoInsuranceUI");
        frame.setDefaultCloseOperation(javax.swing.WindowConstants.EXIT_ON_CLOSE);
        // Create and set up the content pane.
        com.coveros.training.autoinsurance.AutoInsuranceUI newContentPane = new com.coveros.training.autoinsurance.AutoInsuranceUI(frame);
        newContentPane.setOpaque(true);// content panes must be opaque

        frame.setContentPane(newContentPane);
        // Display the window.
        frame.pack();
        frame.setVisible(true);
    }

    public static void main(java.lang.String[] args) {
        // Schedule a job for the event-dispatching thread:
        // creating and showing this application's GUI.
        javax.swing.SwingUtilities.invokeLater(() -> com.coveros.training.autoinsurance.AutoInsuranceUI.createAndShowGUI());
    }

    // stops and closes the application
    public void close() {
        this.frame.dispose();
        java.lang.System.exit(0);
    }
}

