/**
 * This example connects to a coverage agent that run in output mode
 * <code>tcpserver</code> and requests execution data. The collected data is
 * dumped to a local file.
 */
public class ExecutionDataClient {
    private static final java.lang.String ADDRESS = "localhost";

    /**
     * Starts the Jacoco execution data request.
     * First argument is the port to connect to, second is the file to write to.
     */
    public static void main(final java.lang.String[] args) throws java.io.IOException {
        int port = java.lang.Integer.parseInt(args[0]);
        java.lang.String destfile = args[1];
        final java.io.FileOutputStream localFile = new java.io.FileOutputStream(destfile);
        final org.jacoco.core.data.ExecutionDataWriter localWriter = new org.jacoco.core.data.ExecutionDataWriter(localFile);
        // Open a socket to the coverage agent:
        try (java.net.Socket socket = new java.net.Socket(java.net.InetAddress.getByName(com.coveros.training.autoinsurance.ExecutionDataClient.ADDRESS), port)) {
            final org.jacoco.core.runtime.RemoteControlWriter writer = new org.jacoco.core.runtime.RemoteControlWriter(socket.getOutputStream());
            final org.jacoco.core.runtime.RemoteControlReader reader = new org.jacoco.core.runtime.RemoteControlReader(socket.getInputStream());
            reader.setSessionInfoVisitor(localWriter);
            reader.setExecutionDataVisitor(localWriter);
            // Send a dump command and read the response:
            writer.visitDumpCommand(true, true);
            if (!reader.read()) {
                throw new java.io.IOException("Socket closed unexpectedly.");
            }
        }
        localFile.close();
    }

    private ExecutionDataClient() {
    }
}

