/**
 * helper methods to assert that certain things in our code are true,
 * or else we throw an exception.
 */
public class CheckUtils {
    private CheckUtils() {
        // using a private constructor to hide the implicit public one.
    }

    /**
     * Asserts that the integer value received is 1 or above.
     *
     * @param parameter
     * 		a value to check for being positive
     * @throws IllegalArgumentException
     * 		if the input isn't a positive integer
     */
    public static void IntParameterMustBePositive(long parameter) {
        if (parameter <= 0) {
            throw new java.lang.IllegalArgumentException("int value must be 1 or above.");
        }
    }

    /**
     * Makes sure the input value is a valid string of length 1 or greater
     *
     * @param values
     * 		the strings to check
     * @throws IllegalArgumentException
     * 		if the string is null or empty
     */
    public static void StringMustNotBeNullOrEmpty(java.lang.String... values) {
        for (java.lang.String value : values) {
            if ((value == null) || value.isEmpty()) {
                throw new java.lang.IllegalArgumentException("string must not be null or empty at this point");
            }
        }
    }

    /**
     * Used as a general invariant declaration in our code
     *
     * @param mustBeTrue
     * 		this is a predicate that must be true,
     * 		otherwise we'll throw an {@link AssertionException}
     * @param message
     * 		the message to be passed along as part of the exception
     */
    public static void mustBeTrueAtThisPoint(boolean mustBeTrue, java.lang.String message) {
        if (!mustBeTrue) {
            throw new com.coveros.training.helpers.AssertionException(message);
        }
    }
}

