/**
 * Some simple helper methods for Strings.
 */
public class StringUtils {
    private StringUtils() {
        // using a private constructor to hide the implicit public one.
    }

    /**
     * checks the String you pass in; if it's null, return an empty String.
     * Otherwise, return the unchanged string.
     */
    public static java.lang.String makeNotNullable(@org.checkerframework.checker.nullness.qual.Nullable
    java.lang.String s) {
        return s == null ? "" : s;
    }

    // a table of some of the values that may need to be
    // escaped in JSON strings
    static final byte SINGLE_QUOTE = 39;

    static final byte DOUBLE_QUOTE = 34;

    static final byte BACKSLASH = 92;

    static final byte NEW_LINE = 10;

    static final byte CARRIAGE_RETURN = 13;

    static final byte TAB = 9;

    static final byte BACKSPACE = 8;

    static final byte FORM_FEED = 12;

    /**
     * Given a string, replaces characters so that it is safe to use
     * as JSON
     *
     * @param value
     * 		String value to convert
     * @return a properly escaped string, usable in JSON
     */
    public static java.lang.String escapeForJson(java.lang.String value) {
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        org.apache.logging.log4j.core.util.JsonUtils.quoteAsString(value, sb);
        return sb.toString();
    }
}

public class StringUtilsTests {
    @org.junit.Test
    public void testShouldConvertNullToEmptyString() {
        final java.lang.String s = com.coveros.training.helpers.StringUtils.makeNotNullable(null);
        Assert.assertEquals("", s);
    }

    @org.junit.Test
    public void testShouldNotAlterNonNullString() {
        final java.lang.String s = com.coveros.training.helpers.StringUtils.makeNotNullable("abc");
        Assert.assertEquals("abc", s);
    }

    /**
     * JSON won't parse if it has a double quote in a string
     */
    @org.junit.Test
    public void testEscapeForJson_ShouldEscapeDoubleQuote() {
        final java.lang.String expectedResult = new java.lang.String(new byte[]{ com.coveros.training.helpers.StringUtils.BACKSLASH, com.coveros.training.helpers.StringUtils.DOUBLE_QUOTE });
        final java.lang.String inputString = new java.lang.String(new byte[]{ com.coveros.training.helpers.StringUtils.DOUBLE_QUOTE });
        java.lang.String result = com.coveros.training.helpers.StringUtils.escapeForJson(inputString);
        Assert.assertEquals(expectedResult, result);
    }

    /**
     * Testing another potential problem with a JSON string
     */
    @org.junit.Test
    public void testEscapeForJson_ShouldEscapeBackslash() {
        final java.lang.String expectedResult = new java.lang.String(new byte[]{ com.coveros.training.helpers.StringUtils.BACKSLASH, com.coveros.training.helpers.StringUtils.BACKSLASH });
        final java.lang.String inputString = new java.lang.String(new byte[]{ com.coveros.training.helpers.StringUtils.BACKSLASH });
        java.lang.String result = com.coveros.training.helpers.StringUtils.escapeForJson(inputString);
        Assert.assertEquals(expectedResult, result);
    }
}

