    private com.coveros.training.library.domainobjects.Book myBook = com.coveros.training.library.domainobjects.Book.createEmpty();

    private java.lang.String myBookTitle = "";

    private java.lang.String myBorrowerName = "";

    private com.coveros.training.library.domainobjects.Borrower myBorrower = com.coveros.training.library.domainobjects.Borrower.createEmpty();

    private final java.sql.Date JAN_1ST = java.sql.Date.valueOf(java.time.LocalDate.of(2018, java.time.Month.JANUARY, 1));

    private com.coveros.training.library.LibraryUtils libraryUtils = com.coveros.training.library.LibraryUtils.createEmpty();

    private final java.sql.Date JAN_2ND = java.sql.Date.valueOf(java.time.LocalDate.of(2018, java.time.Month.JANUARY, 2));

    private com.coveros.training.library.domainobjects.LibraryActionResults libraryActionResults = com.coveros.training.library.domainobjects.LibraryActionResults.NULL;

    private final com.coveros.training.persistence.IPersistenceLayer pl = new com.coveros.training.persistence.PersistenceLayer();

    /**
     * Set up the databases, clear them, initialize the Library Utility with them.
     */
    private void initializeEmptyDatabaseAndUtility() {
        pl.cleanAndMigrateDatabase();
        libraryUtils = new com.coveros.training.library.LibraryUtils();
    }

    @io.cucumber.java.en.Given("^a borrower, \"([^\"]*)\", is registered$")
    public void aBorrowerIsRegistered(java.lang.String borrowerName) {
