    public void theyTryToCheckOutTheBookOn(java.lang.String date) {
        java.sql.Date borrowTime = java.sql.Date.valueOf(java.time.LocalDate.parse(date, java.time.format.DateTimeFormatter.ofPattern("MMMM dd, yyyy")));
        libraryUtils.lendBook(myBook, myBorrower, borrowTime);
    }

    @io.cucumber.java.en.Then("^the system indicates the book is loaned to them on that date$")
    public void theSystemIndicatesTheBookIsLoanedToThemOnThatDate() {
        final com.coveros.training.library.domainobjects.Loan loan = libraryUtils.searchForLoanByBook(myBook);
        org.junit.Assert.assertEquals(java.sql.Date.valueOf("2018-01-31"), loan.checkoutDate);
    }

    @io.cucumber.java.en.When("^they try to check out the book$")
    public void theyCheckOutTheBook() {
        libraryUtils.lendBook(myBook, myBorrower, JAN_2ND);
    }

    @io.cucumber.java.en.Then("^the system indicates the book is loaned to them on some date$")
    public void theSystemIndicatesTheBookIsLoanedToThemOnSomeDate() {
        final com.coveros.training.library.domainobjects.Loan loan = libraryUtils.searchForLoanByBook(myBook);
        org.junit.Assert.assertEquals(java.sql.Date.valueOf("2018-01-31"), loan.checkoutDate);
