public class LendingTests {
    private static final java.sql.Date BORROW_DATE = java.sql.Date.valueOf(java.time.LocalDate.of(2018, java.time.Month.JANUARY, 1));

    private static final java.lang.String BORROWER_A_NAME = "borrower_a";

    private static final java.lang.String BORROWER_B_NAME = "borrower_b";

    private static final java.lang.String TITLE = "Some book";

    private static final com.coveros.training.library.domainobjects.Book SAMPLE_BOOK = new com.coveros.training.library.domainobjects.Book(1, com.coveros.training.library.LendingTests.TITLE);

    private static final com.coveros.training.library.domainobjects.Borrower SAMPLE_BORROWER_A = new com.coveros.training.library.domainobjects.Borrower(1, com.coveros.training.library.LendingTests.BORROWER_A_NAME);

    private static final com.coveros.training.library.domainobjects.Borrower SAMPLE_BORROWER_B = new com.coveros.training.library.domainobjects.Borrower(1, com.coveros.training.library.LendingTests.BORROWER_B_NAME);

    private final com.coveros.training.library.LibraryUtils libraryUtils = org.mockito.Mockito.spy(com.coveros.training.library.LibraryUtils.class);

    /**
     * If a borrower and a book are registered, a user should be able to borrow it.
     */
    @org.junit.Test
    public void shouldLendToUser() {
        mockSearchForLoan();
        mockThatLoanIsCreated(com.coveros.training.library.LendingTests.SAMPLE_BOOK, com.coveros.training.library.LendingTests.SAMPLE_BORROWER_A, com.coveros.training.library.LendingTests.BORROW_DATE);
        final com.coveros.training.library.domainobjects.LibraryActionResults libraryActionResults = libraryUtils.lendBook(com.coveros.training.library.LendingTests.SAMPLE_BOOK, com.coveros.training.library.LendingTests.SAMPLE_BORROWER_A, com.coveros.training.library.LendingTests.BORROW_DATE);
        org.junit.Assert.assertEquals(com.coveros.training.library.domainobjects.LibraryActionResults.SUCCESS, libraryActionResults);
    }

    private void mockThatLoanIsCreated(com.coveros.training.library.domainobjects.Book book, com.coveros.training.library.domainobjects.Borrower borrower, java.sql.Date borrowDate) {
        org.mockito.Mockito.doNothing().when(libraryUtils).createLoan(book, borrower, borrowDate);
