 */
@javax.servlet.annotation.MultipartConfig
@javax.servlet.annotation.WebServlet(name = "LibraryBookListSearch", urlPatterns = { "/book" }, loadOnStartup = 1)
public class LibraryBookListSearchServlet extends javax.servlet.http.HttpServlet {
    private static final long serialVersionUID = -56598540573518235L;

    private static final org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(com.coveros.training.library.LibraryBookListSearchServlet.class);

    public static final java.lang.String RESULT = "result";

    static com.coveros.training.library.LibraryUtils libraryUtils = new com.coveros.training.library.LibraryUtils();

    @java.lang.Override
    protected void doGet(javax.servlet.http.HttpServletRequest request, javax.servlet.http.HttpServletResponse response) {
        final java.lang.String idString = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter("id"));
        final java.lang.String title = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter("title"));
        java.lang.String result;
        if (idString.isEmpty() && title.isEmpty()) {
            result = listAllBooks();
        } else if ((!idString.isEmpty()) && title.isEmpty()) {
            result = searchById(idString);
        } else if (idString.isEmpty()) {
            result = searchByTitle(title);
        } else {
            // both id and title have an input
            com.coveros.training.library.LibraryBookListSearchServlet.logger.info("Received request for books, by title and id - id {} and title {}", idString, title);
            result = "Error: please search by either title or id, not both";
        }
        request.setAttribute(com.coveros.training.library.LibraryBookListSearchServlet.RESULT, result);
        com.coveros.training.helpers.ServletUtils.forwardToRestfulResult(request, response, com.coveros.training.library.LibraryBookListSearchServlet.logger);
    }

    private java.lang.String searchByTitle(java.lang.String title) {
        com.coveros.training.library.LibraryBookListSearchServlet.logger.info("Received request for books, name requested - searching for book by title {}", title);
        final com.coveros.training.library.domainobjects.Book book = com.coveros.training.library.LibraryBookListSearchServlet.libraryUtils.searchForBookByTitle(title);
        if (book.isEmpty()) {
            return "No books found with a title of " + title;
        }
        return ("[" + book.toOutputString()) + "]";
    }

    private java.lang.String searchById(java.lang.String idString) {
        com.coveros.training.library.LibraryBookListSearchServlet.logger.info("Received request for books, id requested - searching for book by id {}", idString);
        int id;
        try {
            id = java.lang.Integer.parseInt(idString);
        } catch (java.lang.NumberFormatException ex) {
            return "Error: could not parse the book id as an integer";
        }
        final com.coveros.training.library.domainobjects.Book book = com.coveros.training.library.LibraryBookListSearchServlet.libraryUtils.searchForBookById(id);
        if (book.isEmpty()) {
            return "No books found with an id of " + idString;
        }
        return ("[" + book.toOutputString()) + "]";
    }

    private java.lang.String listAllBooks() {
        com.coveros.training.library.LibraryBookListSearchServlet.logger.info("Received request for books, no title or id requested - listing all books");
        final java.util.List<com.coveros.training.library.domainobjects.Book> books = com.coveros.training.library.LibraryBookListSearchServlet.libraryUtils.listAllBooks();
        final java.lang.String allBooks = books.stream().map(com.coveros.training.library.domainobjects.Book::toOutputString).collect(java.util.stream.Collectors.joining(","));
        if (allBooks.isEmpty()) {
            return "No books exist in the database";
        }
        return ("[" + allBooks) + "]";
    }
}

