/**
 * Web API to lend a book to a borrower
 */
@javax.servlet.annotation.WebServlet(name = "LibraryLendServlet", urlPatterns = { "/lend" }, loadOnStartup = 1)
public class LibraryLendServlet extends javax.servlet.http.HttpServlet {
    private static final long serialVersionUID = -6507483398690297645L;

    private static final org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(com.coveros.training.library.LibraryLendServlet.class);

    static com.coveros.training.library.LibraryUtils libraryUtils = new com.coveros.training.library.LibraryUtils();

    @java.lang.Override
    protected void doPost(javax.servlet.http.HttpServletRequest request, javax.servlet.http.HttpServletResponse response) {
        com.coveros.training.library.domainobjects.LibraryActionResults libraryActionResults;
        final java.lang.String book = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter("book"));
        request.setAttribute("book", book);
        final java.lang.String borrower = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter("borrower"));
        request.setAttribute("borrower", borrower);
        if (book.isEmpty()) {
            libraryActionResults = com.coveros.training.library.domainobjects.LibraryActionResults.NO_BOOK_TITLE_PROVIDED;
        } else if (borrower.isEmpty()) {
            libraryActionResults = com.coveros.training.library.domainobjects.LibraryActionResults.NO_BORROWER_PROVIDED;
        } else {
            final java.sql.Date now = getDateNow();
            request.setAttribute("date", now.toString());
            com.coveros.training.library.LibraryLendServlet.logger.info("received request to lend a book, {}, to {}", book, borrower);
            libraryActionResults = com.coveros.training.library.LibraryLendServlet.libraryUtils.lendBook(book, borrower, now);
        }
        request.setAttribute("result", libraryActionResults.toString());
        request.setAttribute("return_page", "library.html");
        com.coveros.training.helpers.ServletUtils.forwardToResult(request, response, com.coveros.training.library.LibraryLendServlet.logger);
    }

    /**
     * Wrapping the call to get a date for now,
     * so it's easier to stub for testing.
     */
    java.sql.Date getDateNow() {
        return java.sql.Date.valueOf(java.time.LocalDate.now());
    }
}

