        }
        com.coveros.training.library.LibraryUtils.logger.info("search for book with title: {}", title);
        final com.coveros.training.library.domainobjects.Book book = persistence.searchBooksByTitle(title).orElse(com.coveros.training.library.domainobjects.Book.createEmpty());
        if (book.isEmpty()) {
            com.coveros.training.library.LibraryUtils.logger.info("No book found with title of {}", title);
        } else {
            com.coveros.training.library.LibraryUtils.logger.info("book found with title of {}", title);
        }
        return book;
    }

