    public com.coveros.training.library.domainobjects.LibraryActionResults deleteBook(com.coveros.training.library.domainobjects.Book book) {
        com.coveros.training.library.LibraryUtils.logger.info("deleting a book.  id: {}, title: {}", book.id, book.title);
        final com.coveros.training.library.domainobjects.Book bookInDatabase = searchForBookByTitle(book.title);
        if (bookInDatabase.isEmpty()) {
            com.coveros.training.library.LibraryUtils.logger.info("book not found in database.  Therefore, obviously, cannot be deleted");
            return com.coveros.training.library.domainobjects.LibraryActionResults.NON_REGISTERED_BOOK_CANNOT_BE_DELETED;
        }
        persistence.deleteBook(book.id);
        com.coveros.training.library.LibraryUtils.logger.info("book with title: {} and id: {} was deleted", bookInDatabase.title, bookInDatabase.id);
        return com.coveros.training.library.domainobjects.LibraryActionResults.SUCCESS;
