public class AckServlet extends javax.servlet.http.HttpServlet {
    private static final long serialVersionUID = 5669410483481180165L;

    public static final java.lang.String RESULT = "result";

    static org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(com.coveros.training.mathematics.AckServlet.class);

    private int putNumberInRequest(java.lang.String itemName, javax.servlet.http.HttpServletRequest request) {
        int item = java.lang.Integer.parseInt(request.getParameter(itemName));
        request.setAttribute(itemName, item);
        return item;
