@javax.servlet.annotation.WebServlet(name = "DbServlet", urlPatterns = { "/flyway" }, loadOnStartup = 1)
public class DbServlet extends javax.servlet.http.HttpServlet {
    private static final long serialVersionUID = 1960160729302133928L;

    private final com.coveros.training.persistence.IPersistenceLayer pl;

    public DbServlet() {
        pl = new com.coveros.training.persistence.PersistenceLayer();
    }

    public DbServlet(com.coveros.training.persistence.IPersistenceLayer pl) {
        this.pl = pl;
    }

    private static final java.lang.String RESULT = "result";

    private static final org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(com.coveros.training.persistence.DbServlet.class);

    @java.lang.Override
    protected void doGet(javax.servlet.http.HttpServletRequest request, javax.servlet.http.HttpServletResponse response) {
        final java.lang.String action = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter("action"));
        switch (action) {
            case "clean" :
                com.coveros.training.persistence.DbServlet.logger.info("received request to clean the database - i.e. remove all data and schema");
                pl.cleanDatabase();
                request.setAttribute(com.coveros.training.persistence.DbServlet.RESULT, "cleaned");
                break;
            case "migrate" :
                com.coveros.training.persistence.DbServlet.logger.info("received request to migrate the database - i.e. add schema, but no data");
                pl.migrateDatabase();
                request.setAttribute(com.coveros.training.persistence.DbServlet.RESULT, "migrated");
                break;
            default :
                com.coveros.training.persistence.DbServlet.logger.info("received request to clean, then migrate the database - i.e. putting it a fresh state with no data");
                pl.cleanAndMigrateDatabase();
                request.setAttribute(com.coveros.training.persistence.DbServlet.RESULT, "cleaned and migrated");
        }
        request.setAttribute("return_page", "library.html");
        com.coveros.training.helpers.ServletUtils.forwardToResult(request, response, com.coveros.training.persistence.DbServlet.logger);
    }
}

