/**
 * a POJO container for the parameters for the {@link SqlData} object.
 */
public final class ParameterObject<T> {
    /**
     * The data we are injecting into the SQL statement
     */
    final java.lang.Object data;

    /**
     * The type of the data we are injecting into the SQL statement (e.g. Integer, String, etc.)
     */
    final java.lang.Class<T> type;

    ParameterObject(java.lang.Object data, java.lang.Class<T> type) {
        this.data = data;
        this.type = type;
    }

    public final boolean equals(@org.checkerframework.checker.nullness.qual.Nullable
    java.lang.Object obj) {
        if (obj == null) {
            return false;
        }
        if (obj == this) {
            return true;
        }
        if (obj.getClass() != getClass()) {
            return false;
        }
        com.coveros.training.persistence.ParameterObject<?> rhs = ((com.coveros.training.persistence.ParameterObject<?>) (obj));
        return new org.apache.commons.lang3.builder.EqualsBuilder().append(data, rhs.data).append(type, rhs.type).isEquals();
    }

    public final int hashCode() {
        // you pick a hard-coded, randomly chosen, non-zero, odd number
        // ideally different for each class
        return new org.apache.commons.lang3.builder.HashCodeBuilder(63, 7).append(data).append(type).toHashCode();
    }

    public static com.coveros.training.persistence.ParameterObject<java.lang.Void> createEmpty() {
        return new com.coveros.training.persistence.ParameterObject<>("", java.lang.Void.class);
    }

    public boolean isEmpty() {
        return this.equals(com.coveros.training.persistence.ParameterObject.createEmpty());
    }

    public final java.lang.String toString() {
        return org.apache.commons.lang3.builder.ToStringBuilder.reflectionToString(this);
    }
}

public class ParameterObjectTests {
    @org.junit.Test
    public void testShouldHaveEqualsAndHashcodeImplementedCorrectly() {
        nl.jqno.equalsverifier.EqualsVerifier.forClass(com.coveros.training.persistence.ParameterObject.class).verify();
    }

    @org.junit.Test
    public void testShouldOutputGoodString() {
        final com.coveros.training.persistence.ParameterObject<java.lang.String> parameterObject = com.coveros.training.persistence.ParameterObjectTests.createTestParameterObject();
        org.junit.Assert.assertTrue("toString was: " + parameterObject.toString(), parameterObject.toString().contains("data=abc123,type=class java.lang.String"));
    }

    private static com.coveros.training.persistence.ParameterObject<java.lang.String> createTestParameterObject() {
        return new com.coveros.training.persistence.ParameterObject<>("abc123", java.lang.String.class);
    }

    @org.junit.Test
    public void testCanCreateEmpty() {
        final com.coveros.training.persistence.ParameterObject<java.lang.Void> parameterObject = com.coveros.training.persistence.ParameterObject.createEmpty();
        org.junit.Assert.assertTrue(parameterObject.isEmpty());
