public class PersistenceLayer implements com.coveros.training.persistence.IPersistenceLayer {
    /* ==========================================================
    ==========================================================

    Class construction - details of making this class

    ==========================================================
    ==========================================================
     */
    private final javax.sql.DataSource dataSource;

    public PersistenceLayer() {
        this(com.coveros.training.persistence.PersistenceLayer.obtainConnectionPool());
    }

    PersistenceLayer(javax.sql.DataSource ds) {
        dataSource = ds;
    }

    private static org.h2.jdbcx.JdbcConnectionPool obtainConnectionPool() {
        return org.h2.jdbcx.JdbcConnectionPool.create("jdbc:h2:mem:training;MODE=PostgreSQL", "", "");
    }

    /* ==========================================================
    ==========================================================

    Micro ORM
    Demo has a simplistic Object Relational Mapper (ORM)
    implementation.  These are the methods that comprise
    the mechanisms for that.

    In comparison, a gargantuan project like Hibernate
    would consist of a heckuva-lot-more than this.  That's
    why this one is termed, "micro"

    ==========================================================
    ==========================================================
     */
    /**
     * This command provides a template to execute updates (including inserts) on the database
     */
    void executeUpdateTemplate(java.lang.String description, java.lang.String preparedStatement, java.lang.Object... params) {
        final com.coveros.training.persistence.SqlData<java.lang.Object> sqlData = new com.coveros.training.persistence.SqlData<>(description, preparedStatement, params);
        try (java.sql.Connection connection = dataSource.getConnection()) {
            try (java.sql.PreparedStatement st = prepareStatementWithKeys(sqlData, connection)) {
                executeUpdateOnPreparedStatement(sqlData, st);
            }
        } catch (java.sql.SQLException ex) {
            throw new com.coveros.training.persistence.SqlRuntimeException(ex);
        }
    }

    public long executeInsertTemplate(java.lang.String description, java.lang.String preparedStatement, java.lang.Object... params) {
        final com.coveros.training.persistence.SqlData<java.lang.Object> sqlData = new com.coveros.training.persistence.SqlData<>(description, preparedStatement, params);
        try (java.sql.Connection connection = dataSource.getConnection()) {
            try (java.sql.PreparedStatement st = prepareStatementWithKeys(sqlData, connection)) {
                return executeInsertOnPreparedStatement(sqlData, st);
            }
        } catch (java.sql.SQLException ex) {
            throw new com.coveros.training.persistence.SqlRuntimeException(ex);
        }
    }

    <T> long executeInsertOnPreparedStatement(com.coveros.training.persistence.SqlData<T> sqlData, java.sql.PreparedStatement st) throws java.sql.SQLException {
        sqlData.applyParametersToPreparedStatement(st);
        st.executeUpdate();
        try (java.sql.ResultSet generatedKeys = st.getGeneratedKeys()) {
            long newId;
            if (generatedKeys.next()) {
                newId = generatedKeys.getLong(1);
                assert newId > 0;
            } else {
                throw new com.coveros.training.persistence.SqlRuntimeException((("failed Sql.  Description: " + sqlData.description) + " SQL code: ") + sqlData.preparedStatement);
            }
            return newId;
        }
    }

    private <T> void executeUpdateOnPreparedStatement(com.coveros.training.persistence.SqlData<T> sqlData, java.sql.PreparedStatement st) throws java.sql.SQLException {
        sqlData.applyParametersToPreparedStatement(st);
        st.executeUpdate();
    }

    /**
     * A helper method.  Simply creates a prepared statement that
     * always returns the generated keys from the database, like
     * when you insert a new row of data in a table with auto-generating primary key.
     *
     * @param sqlData
     * 		see {@link SqlData}
     * @param connection
     * 		a typical {@link Connection}
     */
    private <T> java.sql.PreparedStatement prepareStatementWithKeys(com.coveros.training.persistence.SqlData<T> sqlData, java.sql.Connection connection) throws java.sql.SQLException {
        return connection.prepareStatement(sqlData.preparedStatement, java.sql.Statement.RETURN_GENERATED_KEYS);
    }

    <R> java.util.Optional<R> runQuery(com.coveros.training.persistence.SqlData<R> sqlData) {
        try (java.sql.Connection connection = dataSource.getConnection()) {
            try (java.sql.PreparedStatement st = connection.prepareStatement(sqlData.preparedStatement)) {
                sqlData.applyParametersToPreparedStatement(st);
                try (java.sql.ResultSet resultSet = st.executeQuery()) {
                    return sqlData.extractor.apply(resultSet);
                }
            }
        } catch (java.sql.SQLException ex) {
            throw new com.coveros.training.persistence.SqlRuntimeException(ex);
        }
    }

    /**
     * This is an interface to a wrapper around {@link Function} so we can catch exceptions
     * in the generic function.
     *
     * @param <R>
     * 		The return type
     * @param <E>
     * 		The type of the exception
     */
    @java.lang.FunctionalInterface
    private interface ThrowingFunction<R, E extends java.lang.Exception> {
        R apply(java.sql.ResultSet resultSet) throws E;
    }

    /**
     * This wraps the throwing function, so that we are not forced to
     * catch an exception in our ordinary code - it's caught and handled
     * here.
     *
     * @param throwingFunction
     * 		a lambda that throws a checked exception we have to handle.
     * 		specifically in this case that's a SqlRuntimeException
     * @param <R>
     * 		the type of value returned
     * @return returns a function that runs and returns a function wrapped with an exception handler
     */
    static <R> java.util.function.Function<java.sql.ResultSet, R> throwingFunctionWrapper(com.coveros.training.persistence.PersistenceLayer.ThrowingFunction<R, java.lang.Exception> throwingFunction) {
        return resultSet -> {
            try {
                return throwingFunction.apply(resultSet);
            } catch (java.lang.Exception ex) {
                throw new com.coveros.training.persistence.SqlRuntimeException(ex);
            }
        };
    }

    /**
     * Accepts a function to extract data from a {@link ResultSet} and
     * removes some boilerplate with handling its response.
     * Works in conjunction with {@link #throwingFunctionWrapper}
     *
     * @param extractorFunction
     * 		a function that extracts data from a {@link ResultSet}
     * @param <T>
     * 		the type of data we'll retrieve from the {@link ResultSet}
     * @return either the type of data wrapped with an optional, or {@link Optional#empty}
     */
    private <T> java.util.function.Function<java.sql.ResultSet, java.util.Optional<T>> createExtractor(com.coveros.training.persistence.PersistenceLayer.ThrowingFunction<java.util.Optional<T>, java.lang.Exception> extractorFunction) {
        return com.coveros.training.persistence.PersistenceLayer.throwingFunctionWrapper(rs -> {
            if (rs.next()) {
                return extractorFunction.apply(rs);
            } else {
                return java.util.Optional.empty();
            }
        });
    }

    /* ==========================================================
    ==========================================================

    Business functions
    loaning out books, registering users, etc

    ==========================================================
    ==========================================================
     */
    // Library functions
    @java.lang.Override
    public long saveNewBorrower(java.lang.String borrowerName) {
        com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(borrowerName);
        return executeInsertTemplate("adds a new library borrower", "INSERT INTO library.borrower (name) VALUES (?);", borrowerName);
    }

    @java.lang.Override
    public long createLoan(com.coveros.training.library.domainobjects.Book book, com.coveros.training.library.domainobjects.Borrower borrower, java.sql.Date borrowDate) {
        return executeInsertTemplate("Creates a new loan of a book to a borrower", "INSERT INTO library.loan (book, borrower, borrow_date) VALUES (?, ?, ?);", book.id, borrower.id, borrowDate);
    }

    @java.lang.Override
    public long saveNewBook(java.lang.String bookTitle) {
        com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(bookTitle);
        return executeInsertTemplate("Creates a new book in the database", "INSERT INTO library.book (title) VALUES (?);", bookTitle);
    }

    @java.lang.Override
    public void updateBorrower(long id, java.lang.String borrowerName) {
        com.coveros.training.helpers.CheckUtils.IntParameterMustBePositive(id);
        com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(borrowerName);
        executeUpdateTemplate("Updates the borrower's data", "UPDATE library.borrower SET name = ? WHERE id = ?;", borrowerName, id);
    }

    @java.lang.Override
    public void deleteBook(long id) {
        com.coveros.training.helpers.CheckUtils.IntParameterMustBePositive(id);
        executeUpdateTemplate("Deletes a book from the database", "DELETE FROM library.book WHERE id = ?;", id);
    }

    @java.lang.Override
    public void deleteBorrower(long id) {
        com.coveros.training.helpers.CheckUtils.IntParameterMustBePositive(id);
        executeUpdateTemplate("Deletes a borrower from the database", "DELETE FROM library.borrower WHERE id = ?;", id);
    }

    @java.lang.Override
    public java.util.Optional<java.lang.String> getBorrowerName(long id) {
        com.coveros.training.helpers.CheckUtils.IntParameterMustBePositive(id);
        java.util.function.Function<java.sql.ResultSet, java.util.Optional<java.lang.String>> extractor = createExtractor(rs -> java.util.Optional.of(com.coveros.training.helpers.StringUtils.makeNotNullable(rs.getString(1))));
        return runQuery(new com.coveros.training.persistence.SqlData<>("get a borrower's name by their id", "SELECT name FROM library.borrower WHERE id = ?;", extractor, id));
    }

    @java.lang.Override
    public java.util.Optional<com.coveros.training.library.domainobjects.Borrower> searchBorrowerDataByName(java.lang.String borrowerName) {
        com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(borrowerName);
        java.util.function.Function<java.sql.ResultSet, java.util.Optional<com.coveros.training.library.domainobjects.Borrower>> extractor = createExtractor(rs -> {
            long id = rs.getLong(1);
            java.lang.String name = com.coveros.training.helpers.StringUtils.makeNotNullable(rs.getString(2));
            return java.util.Optional.of(new com.coveros.training.library.domainobjects.Borrower(id, name));
        });
        return runQuery(new com.coveros.training.persistence.SqlData<>("search for details on a borrower by name", "SELECT id, name FROM library.borrower WHERE name = ?;", extractor, borrowerName));
    }

    @java.lang.Override
    public java.util.Optional<com.coveros.training.library.domainobjects.Book> searchBooksByTitle(java.lang.String bookTitle) {
        com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(bookTitle);
