            long id = rs.getLong(1);
            return java.util.Optional.of(new com.coveros.training.library.domainobjects.Book(id, bookTitle));
        });
        return runQuery(new com.coveros.training.persistence.SqlData<>("search for a book by title", "SELECT id FROM library.book WHERE title = ?;", extractor, bookTitle));
