            long borrowerId = rs.getLong(1);
            java.lang.String name = com.coveros.training.helpers.StringUtils.makeNotNullable(rs.getString(2));
            return java.util.Optional.of(new com.coveros.training.library.domainobjects.Borrower(borrowerId, name));
