    private java.util.Optional<java.util.List<com.coveros.training.library.domainobjects.Book>> listBooks(java.lang.String description, java.lang.String sqlCode) {
        java.util.function.Function<java.sql.ResultSet, java.util.Optional<java.util.List<com.coveros.training.library.domainobjects.Book>>> extractor = createExtractor(rs -> {
