    @java.lang.Override
    public java.util.Optional<java.util.List<com.coveros.training.library.domainobjects.Loan>> searchForLoanByBorrower(com.coveros.training.library.domainobjects.Borrower borrower) {
        java.util.function.Function<java.sql.ResultSet, java.util.Optional<java.util.List<com.coveros.training.library.domainobjects.Loan>>> extractor = createExtractor(rs -> {
            java.util.List<com.coveros.training.library.domainobjects.Loan> loans = new java.util.ArrayList<>();
            do {
                final long loanId = rs.getLong(1);
                final java.sql.Date borrowDate = rs.getDate(2);
