                final java.sql.Date borrowDateNotNullable = (borrowDate == null) ? java.sql.Date.valueOf("0000-01-01") : borrowDate;
                loans.add(new com.coveros.training.library.domainobjects.Loan(new com.coveros.training.library.domainobjects.Book(bookId, bookTitle), borrower, loanId, borrowDateNotNullable));
            } while (rs.next() );
