    public java.util.Optional<com.coveros.training.authentication.domainobjects.User> searchForUserByName(java.lang.String username) {
        com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(username);
        java.util.function.Function<java.sql.ResultSet, java.util.Optional<com.coveros.training.authentication.domainobjects.User>> extractor = createExtractor(rs -> {
            final long id = rs.getLong(1);
            return java.util.Optional.of(new com.coveros.training.authentication.domainobjects.User(username, id));
        });
        return runQuery(new com.coveros.training.persistence.SqlData<>("search for a user by id, return that user if found, otherwise return an empty user", "SELECT id  FROM auth.user WHERE name = ?;", extractor, username));
    }

    @java.lang.Override
    public java.util.Optional<java.lang.Boolean> areCredentialsValid(java.lang.String username, java.lang.String password) {
        java.util.function.Function<java.sql.ResultSet, java.util.Optional<java.lang.Boolean>> extractor = createExtractor(rs -> {
            final long id = rs.getLong(1);
            assert id > 0;
            return java.util.Optional.of(true);
        });
        final java.lang.String hexHash = createHashedValueFromPassword(password);
        return runQuery(new com.coveros.training.persistence.SqlData<>("check to see if the credentials for a user are valid", "SELECT id FROM auth.user WHERE name = ? AND password_hash = ?;", extractor, username, hexHash));
    }

    @java.lang.Override
    public void updateUserWithPassword(long id, java.lang.String password) {
        com.coveros.training.helpers.CheckUtils.IntParameterMustBePositive(id);
        java.lang.String hashedPassword = createHashedValueFromPassword(password);
        executeUpdateTemplate("Updates the user's password field with a new hash", "UPDATE auth.user SET password_hash = ? WHERE id = ?;", hashedPassword, id);
    }

    /**
     * Given a password (for example, "password123"), return a
     * hash of that.
     *
     * @param password
     * 		a user's password
     * @return a hash of the password value.  a one-way function that returns a unique value,
    but different than the original, cannot be converted back to its original value.
     */
    private java.lang.String createHashedValueFromPassword(java.lang.String password) {
        com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(password);
        try {
            java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-256");
            byte[] encodedhash = digest.digest(password.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            return com.coveros.training.persistence.PersistenceLayer.bytesToHex(encodedhash);
        } catch (java.security.NoSuchAlgorithmException e) {
            throw new com.coveros.training.persistence.SqlRuntimeException(e);
        }
    }

    /**
     * Converts an array of bytes to their corresponding hex string
     *
     * @param bytes
     * 		an array of bytes
     * @return a hex string of that array
     */
    private static java.lang.String bytesToHex(byte[] bytes) {
        java.lang.StringBuilder hexString = new java.lang.StringBuilder();
        for (byte b : bytes) {
            java.lang.String hex = java.lang.Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    /* ==========================================================
    ==========================================================

    General utility methods

    ==========================================================
    ==========================================================
     */
    public static com.coveros.training.persistence.IPersistenceLayer createEmpty() {
        return new com.coveros.training.persistence.PersistenceLayer(new com.coveros.training.persistence.EmptyDataSource());
    }

    @java.lang.Override
    public boolean isEmpty() {
        return this.dataSource.getClass().equals(com.coveros.training.persistence.EmptyDataSource.class);
    }

    @java.lang.Override
    public void runBackup(java.lang.String backupFileName) {
        try (java.sql.Connection connection = dataSource.getConnection()) {
            try (java.sql.PreparedStatement st = connection.prepareStatement("SCRIPT TO ?")) {
                st.setString(1, backupFileName);
                st.execute();
            }
        } catch (java.sql.SQLException ex) {
            throw new com.coveros.training.persistence.SqlRuntimeException(ex);
        }
    }

    @java.lang.Override
    public void runRestore(java.lang.String backupFileName) {
        java.lang.String dbScriptsDirectory = "src/integration_test/resources/db_sample_files/";
        java.lang.String fullPathToBackup = dbScriptsDirectory + backupFileName;
        try (java.sql.Connection connection = dataSource.getConnection()) {
            try (java.sql.PreparedStatement st = connection.prepareStatement("DROP SCHEMA IF EXISTS ADMINISTRATIVE CASCADE;" + ("DROP SCHEMA IF EXISTS AUTH CASCADE;" + "DROP SCHEMA IF EXISTS LIBRARY CASCADE;"))) {
                st.execute();
            }
            try (java.sql.PreparedStatement st = connection.prepareStatement("RUNSCRIPT FROM ?")) {
                st.setString(1, fullPathToBackup);
                st.execute();
            }
        } catch (java.sql.SQLException ex) {
            throw new com.coveros.training.persistence.SqlRuntimeException(ex);
        }
    }

    /* ==========================================================
    ==========================================================

    Database migration code - using FlywayDb

    ==========================================================
    ==========================================================
     */
    @java.lang.Override
    public void cleanAndMigrateDatabase() {
        cleanDatabase();
        migrateDatabase();
    }

    @java.lang.Override
    public void cleanDatabase() {
        org.flywaydb.core.Flyway flyway = configureFlyway();
        flyway.clean();
    }

    @java.lang.Override
    public void migrateDatabase() {
        org.flywaydb.core.Flyway flyway = configureFlyway();
        flyway.migrate();
    }

    private org.flywaydb.core.Flyway configureFlyway() {
        return org.flywaydb.core.Flyway.configure().schemas("ADMINISTRATIVE", "LIBRARY", "AUTH").dataSource(this.dataSource).load();
    }
}

