/**
 * This class encapsulates some of the actions related to
 * injecting data into a prepared SQL statement, so that
 * we are able to summarize what we want done without
 * all the annoying boilerplate.  See examples like {@link PersistenceLayer#saveNewBorrower}
 * <p>
 * Was necessary to suppress the nullness warnings on this class due to its
 * use of generics.
 * The generic R is the result type - if we ask for a string, R would be a String.
 * On the other hand if R might be a compound type, like Employee.
 */
final class SqlData<R> {
    /**
     * A summary description of what this SQL is doing.
     */
    final java.lang.String description;

    /**
     * This is the String text of the SQL prepared statement.  We're using PostgreSQL,
     * see https://jdbc.postgresql.org/documentation/81/server-prepare.html
     */
    final java.lang.String preparedStatement;

    /**
     * The data that we will inject to the SQL statement.
     */
    private final java.util.List<com.coveros.training.persistence.ParameterObject<?>> params;

    /**
     * A generic function - takes a {@link ResultSet} straight from the database,
     * and then carries out actions on it, per the user's intentions, to convert it
     * into something of type {@link R}.
     */
    public final java.util.function.Function<java.sql.ResultSet, java.util.Optional<R>> extractor;

    SqlData(java.lang.String description, java.lang.String preparedStatement, java.lang.Object... params) {
        this(description, preparedStatement, resultSet -> java.util.Optional.empty(), params);
    }

    /**
     * Creates an object that is used to avoid some of the boilerplate
     * in running database CRUD operations.
     *
     * @param description
     * 		A string that describes in plain English what this SQL does.
     * @param preparedStatement
     * 		The SQL that is run on the database
     * @param extractor
     * 		see {@link #extractor} a function that is run to convert the returned {@link ResultSet} into whatever we want
     */
    SqlData(java.lang.String description, java.lang.String preparedStatement, java.util.function.Function<java.sql.ResultSet, java.util.Optional<R>> extractor, java.lang.Object... params) {
        this.description = description;
        this.preparedStatement = preparedStatement;
        this.params = new java.util.ArrayList<>();
        if (params.length > 0) {
            generateParams(params);
        }
        this.extractor = extractor;
    }

    /**
     * Loads the parameters for this SQL
     *
     * @param params
     */
    private void generateParams(java.lang.Object[] params) {
        for (java.lang.Object param : params) {
            addParameter(param, param.getClass());
        }
    }

    /**
     * A list of the parameters to a particular SQL statement.
     * Add to this list in the order of the statement.
     * For example,
     * for SELECT * FROM USERS WHERE a = ? and b = ?
     * <p>
     * first add the parameter for a, then for b.
     *
     * @param data
     * 		a particular item of data.  Any object will do.  Look at {@link #applyParametersToPreparedStatement(PreparedStatement)}
     * 		to see what we can process.
     * @param clazz
     * 		the class of the thing.  I would rather not use reflection, let's keep it above board for now.
     */
    <T> void addParameter(java.lang.Object data, java.lang.Class<T> clazz) {
        params.add(new com.coveros.training.persistence.ParameterObject<>(data, clazz));
    }

    /**
     * Loop through the parameters that have been added and
     * serially add them to the prepared statement.
     *
     * @param st
     * 		a prepared statement
     */
    void applyParametersToPreparedStatement(java.sql.PreparedStatement st) {
        try {
            for (int i = 1; i <= params.size(); i++) {
                com.coveros.training.persistence.ParameterObject<?> p = params.get(i - 1);
                if (p.type == java.lang.String.class) {
                    st.setString(i, ((java.lang.String) (p.data)));
                } else if (p.type == java.lang.Integer.class) {
                    st.setInt(i, ((java.lang.Integer) (p.data)));
                } else if (p.type == java.lang.Long.class) {
                    st.setLong(i, ((java.lang.Long) (p.data)));
                } else if (p.type == java.sql.Date.class) {
                    st.setDate(i, ((java.sql.Date) (p.data)));
                }
            }
        } catch (java.sql.SQLException e) {
            throw new com.coveros.training.persistence.SqlRuntimeException(e);
        }
    }

    public final boolean equals(@org.checkerframework.checker.nullness.qual.Nullable
    java.lang.Object obj) {
        if (obj == null) {
            return false;
        }
        if (obj == this) {
            return true;
        }
        if (obj.getClass() != getClass()) {
            return false;
        }
        com.coveros.training.persistence.SqlData<?> rhs = ((com.coveros.training.persistence.SqlData<?>) (obj));
        return new org.apache.commons.lang3.builder.EqualsBuilder().append(description, rhs.description).append(preparedStatement, rhs.preparedStatement).append(params, rhs.params).append(extractor, rhs.extractor).isEquals();
    }

    public final int hashCode() {
        // you pick a hard-coded, randomly chosen, non-zero, odd number
        // ideally different for each class
        return new org.apache.commons.lang3.builder.HashCodeBuilder(53, 97).append(description).append(preparedStatement).append(params).append(extractor).toHashCode();
    }

    public final java.lang.String toString() {
        java.lang.StringBuilder paramsString = new java.lang.StringBuilder();
        for (com.coveros.training.persistence.ParameterObject<?> p : params) {
            paramsString.append(p);
        }
        return new org.apache.commons.lang3.builder.ToStringBuilder(this).append("description", description).append("params", paramsString.toString()).append("prepared statement", preparedStatement).toString();
    }

    public static <T> com.coveros.training.persistence.SqlData<T> createEmpty() {
        return new com.coveros.training.persistence.SqlData<>("", "");
    }

    public boolean isEmpty() {
        return this.equals(com.coveros.training.persistence.SqlData.createEmpty());
    }
}

