@javax.servlet.annotation.WebListener
public class WebAppListener implements javax.servlet.ServletContextListener {
    private final com.coveros.training.persistence.IPersistenceLayer pl;

    public WebAppListener() {
        pl = new com.coveros.training.persistence.PersistenceLayer();
    }

    public WebAppListener(com.coveros.training.persistence.IPersistenceLayer pl) {
        this.pl = pl;
    }

    /**
     * Cleans and migrates the database using Flyway.
     * See database migration files like V2__Rest_of_tables_for_auth_and_library.sql
     */
    @java.lang.Override
    public void contextInitialized(javax.servlet.ServletContextEvent sce) {
        // clean the database and configure the schema
        pl.cleanAndMigrateDatabase();
    }

    /**
     * This does nothing, but it's required to implement per the interface.
     */
    @java.lang.Override
    public void contextDestroyed(javax.servlet.ServletContextEvent sce) {
        // do nothing.
    }
}

