public class ApiCalls {
    /**
     * Use the API to register a user
     *
     * @param username
     * 		some username
     * @param password
     * 		a really good password (otherwise it will probably respond with a complaint
     * @return returns the body of the result, if you wish to use it.
     */
    public static java.lang.String registerUser(java.lang.String username, java.lang.String password) {
        try {
            final org.apache.http.client.fluent.Content content = org.apache.http.client.fluent.Request.Post("http://localhost:8080/demo/register").bodyForm(org.apache.http.client.fluent.Form.form().add("username", username).add("password", password).build()).execute().returnContent();
            return content.asString();
        } catch (java.io.IOException e) {
            e.printStackTrace();
            return "";
        }
    }

